import { initialIntakeState, transitionIntake } from './solution';
import type { Parcel, IntakeState, IntakeEvent } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsTypeError(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  if (!(error instanceof TypeError)) throw new Error(message);
}

const waiting: IntakeState = initialIntakeState;
equal(waiting.status, 'waiting', 'initial status');

const parcel: Parcel = { id: 'P-1', sender: 'Ada' };
const arrive: IntakeEvent = { type: 'ARRIVE', parcel };
const reviewing = transitionIntake(waiting, arrive);
equal(reviewing.status, 'reviewing', 'ARRIVE transition');
assert(reviewing !== waiting, 'valid transition returns a fresh state');
if (reviewing.status !== 'reviewing') throw new Error('expected reviewing state');
assert(reviewing.parcel !== parcel, 'arriving parcel must be copied');
equal(reviewing.parcel.id, 'P-1', 'copied parcel id');
equal(reviewing.parcel.sender, 'Ada', 'copied parcel sender');
equal(parcel.id, 'P-1', 'parcel input not mutated');
equal(arrive.type, 'ARRIVE', 'event not mutated');

const storing = transitionIntake(reviewing, { type: 'APPROVE' });
equal(storing.status, 'storing', 'APPROVE transition');
assert(storing !== reviewing, 'APPROVE returns fresh state');
const stored = transitionIntake(storing, { type: 'STORE_OK' });
equal(stored.status, 'stored', 'STORE_OK transition');

const reviewingForReject = transitionIntake(initialIntakeState, { type: 'ARRIVE', parcel: { id: 'P-2', sender: 'Bob' } });
const rejected = transitionIntake(reviewingForReject, { type: 'REJECT' });
equal(rejected.status, 'rejected', 'REJECT transition');

const reviewingForFailure = transitionIntake(initialIntakeState, { type: 'ARRIVE', parcel: { id: 'P-3', sender: 'Cy' } });
const storingForFailure = transitionIntake(reviewingForFailure, { type: 'APPROVE' });
const failureEvent: IntakeEvent = { type: 'STORE_FAILED', reason: 'shelf unavailable' };
const failed = transitionIntake(storingForFailure, failureEvent);
equal(failed.status, 'failed', 'STORE_FAILED transition');
if (failed.status !== 'failed') throw new Error('expected failed state');
equal(failed.reason, 'shelf unavailable', 'failure reason retained');
equal(failureEvent.reason, 'shelf unavailable', 'failure event not mutated');
const retried = transitionIntake(failed, { type: 'RETRY' });
equal(retried.status, 'storing', 'RETRY transition');
assert(retried !== failed, 'RETRY returns fresh state');

const invalid = transitionIntake(reviewing, { type: 'STORE_OK' });
assert(invalid === reviewing, 'event invalid for state returns exact state reference');
const invalidArrival = transitionIntake(reviewing, { type: 'ARRIVE', parcel: { id: 'P-X', sender: 'X' } });
assert(invalidArrival === reviewing, 'second validly formed ARRIVE is ignored by reference');

const resetWaiting = transitionIntake(initialIntakeState, { type: 'RESET' });
equal(resetWaiting.status, 'waiting', 'RESET from waiting');
assert(resetWaiting !== initialIntakeState, 'RESET is valid and returns a fresh state even from waiting');
const resetStored = transitionIntake(stored, { type: 'RESET' });
equal(resetStored.status, 'waiting', 'RESET from stored');
assert(resetStored !== stored, 'RESET from stored returns fresh state');

throwsTypeError(
  () => transitionIntake(initialIntakeState, { type: 'ARRIVE', parcel: { id: '', sender: 'valid' } }),
  'empty parcel id must throw',
);
throwsTypeError(
  () => transitionIntake(initialIntakeState, { type: 'ARRIVE', parcel: { id: 'valid', sender: '' } }),
  'empty sender must throw',
);
throwsTypeError(
  () => transitionIntake(storingForFailure, { type: 'STORE_FAILED', reason: '' }),
  'empty failure reason must throw',
);
throwsTypeError(
  () => transitionIntake(stored, { type: 'ARRIVE', parcel: { id: '', sender: '' } }),
  'malformed parcel must throw even when ARRIVE is not a valid transition',
);
throwsTypeError(
  () => transitionIntake(waiting, { type: 'STORE_FAILED', reason: '' }),
  'malformed reason must throw even when STORE_FAILED is not a valid transition',
);

